import{_ as o,o as e,c as n,ag as r}from"./chunks/framework.rBpyMD18.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1771785132000}'),s={name:"introduction.md"};function a(i,t,d,l,u,c){return e(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>Agentic Engineering Amplified</strong></p><p>Cloding is a universal wrapper that lets you run <strong>Claude Code</strong>, <strong>Gemini CLI</strong>, <strong>Codex CLI</strong>, <strong>OpenCode</strong>, or <strong>GitHub Copilot CLI</strong> — use OpenRouter, Direct API keys, or link to your paid plan.</p><p>Claude Code is a powerful agentic coding tool — it edits files, runs terminal commands, and manages your entire development workflow. But it costs <strong>$5/Mtok input</strong> and <strong>$25/Mtok output</strong>.</p><p><strong>cloding</strong> lets you run the exact same Claude Code experience with any model on <a href="https://openrouter.ai" target="_blank" rel="noreferrer">OpenRouter</a>. Same tools, same file editing, same terminal access — just swap the model underneath.</p><h2 id="why-cloding" tabindex="-1">Why cloding? <a class="header-anchor" href="#why-cloding" aria-label="Permalink to &quot;Why cloding?&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Claude Code</th><th>cloding + Qwen</th></tr></thead><tbody><tr><td><strong>Input cost</strong></td><td>$5.00/Mtok</td><td>$0.12/Mtok</td></tr><tr><td><strong>Output cost</strong></td><td>$25.00/Mtok</td><td>$0.75/Mtok</td></tr><tr><td><strong>Tools &amp; editing</strong></td><td>✅</td><td>✅</td></tr><tr><td><strong>Terminal access</strong></td><td>✅</td><td>✅</td></tr><tr><td><strong>30-min session</strong></td><td>~$5.00</td><td>~$0.12</td></tr></tbody></table><blockquote><p>A typical 30-minute coding session that costs ~$5 with Claude Code costs ~$0.12 with Qwen 3 Coder. That&#39;s <strong>42x cheaper on input</strong>.</p></blockquote><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><p><strong>One-line install</strong> — Standalone binary, no Node.js required. <code>curl | bash</code> on Mac/Linux, <code>irm | iex</code> on Windows. Run <code>cloding setup</code> to install all 5 CLI tools automatically.</p><p><strong>Universal CLI wrapper</strong> — Not just Claude Code. Run Gemini CLI, Codex CLI, GitHub Copilot CLI, or OpenCode — all through one interface with consistent flags and Docker support.</p><p><strong>Flexible auth</strong> — Use OpenRouter for any model, direct API keys (Anthropic, Google, OpenAI), or link to your paid plan (Claude, Gemini, ChatGPT, Copilot). Mix and match per session.</p><p><strong>Docker sandboxing</strong> — Run any CLI tool in an isolated container. No access to your secrets, SSH keys, or host filesystem. Just the workspace you mount.</p><p><strong>Pipeline mode</strong> — Multi-stage coding pipelines with parallel fan-out. Assign different models to different stages: Plan → Explore → Code → Review.</p><p><strong>Zero lock-in</strong> — All flags pass through to the underlying CLI. It&#39;s the same tools you already know, just cheaper and more flexible.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>cloding is a thin wrapper that routes API calls through OpenRouter (or your chosen provider) instead of directly to the default API. When you run <code>cloding</code>, it:</p><ol><li>Resolves your model shortcut to a provider + model ID</li><li>Sets the right environment variables for the chosen CLI tool</li><li>Spawns the CLI (Claude Code, Gemini, Codex, Copilot, or OpenCode)</li></ol><p>That&#39;s it. No forks, no patches, no modified binaries. Just configuration.</p>',19)])])}const g=o(s,[["render",a]]);export{h as __pageData,g as default};
